import * as T from './three.module.js';
import {plantMaize,orchardTree} from './farm-art.js';
import {FIELD} from './crops.js?v=simulation15';
// One shared home-farm scene for the original farm and Frontier. Same coordinates,
// crop meshes, buildings and pen entrances; no persistence or economy writes.
export function buildHomeFarm({scene,mesh,box,cyl,ball,mats,block}){
const worldBuildings=[];function building(x,z,w,d,h,color,label){let g=new T.Group();g.position.set(x,0,z);scene.add(g);worldBuildings.push({g,x,z,w,d,label});box(w,h,d,color,0,h/2+.2,0,g);const pitch=.48, half=w/2+.4, slope=half/Math.cos(pitch);for(const side of [-1,1]){let roof=box(slope,.18,d+.8,'#a75b46',side*half/2,h+.25+half*Math.tan(pitch)/2,0,g);roof.rotation.z=-side*pitch;for(let row=0;row<5;row++){let line=box(slope,.045,.045,'#884c3b',side*half/2,h+.36+half*Math.tan(pitch)/2,-d/2+row*d/4,g);line.rotation.z=-side*pitch;}}box(.15,.15,d+.9,'#d08760',0,h+.3+half*Math.tan(pitch),0,g);for(let k=0;k<Math.floor(w/.55);k++)box(.035,h,.03,'#aa604c',-w/2+k*.55,h/2+.2,d/2+.02,g);box(w*.29,h*.65,.12,mats.wood,0,h*.325+.2,d/2+.08,g);box(.08,h*.65,.15,mats.white,0,h*.325+.2,d/2+.16,g);for(let xx of [-w*.34,w*.34]){box(w*.17,h*.23,.12,'#a8c4c5',xx,h*.62,d/2+.09,g);box(w*.21,.09,.17,mats.white,xx,h*.49,d/2+.14,g)}for(let xx of [-w/2+.1,w/2-.1])box(.14,h,.14,mats.white,xx,h/2+.2,d/2+.05,g);block(x,z,w,d);sign(label,x,h+2,z);return g}
function sign(text,x,y,z){let c=document.createElement('canvas');c.width=512;c.height=100;let q=c.getContext('2d');q.fillStyle='#fff7df';q.beginPath();q.roundRect(0,0,512,90,22);q.fill();q.fillStyle='#40543a';q.font='600 35px system-ui';q.textAlign='center';q.fillText(text,256,58);let s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:false}));s.position.set(x,y,z);s.scale.set(4.2,.83,1);scene.add(s)}building(-8,-10,9,6,4.8,mats.red,'THE RED BARN');building(10,-12,6,5,3.3,'#e2c28b','MEADOW STABLES');building(-17,10,5,4,2.5,'#d4b374','FEED MILL');building(16,8,4,3,2.2,'#d8ac70','HEN HOUSE');
function fence(x,z,w,d){for(let side of [-1,1])for(let i=0;i<=w;i+=2){box(.15,1.2,.15,mats.wood,x-w/2+i,.8,z+side*d/2);if(i<w){let mid=-w/2+i+1;if(side===1&&Math.abs(mid)<1.5)continue;for(let h of [.6,1.1])box(2,.12,.1,mats.white,x+mid,h,z+side*d/2);block(x+mid,z+side*d/2,1.9,.1)}}for(let side of [-1,1])for(let i=0;i<=d;i+=2){box(.15,1.2,.15,mats.wood,x+side*w/2,.8,z-d/2+i);if(i<d){for(let h of [.6,1.1])box(.1,.12,2,mats.white,x+side*w/2,h,z-d/2+i+1);block(x+side*w/2,z-d/2+i+1,.1,1.9)}}}fence(-12,0,12,8);fence(12,-2,12,8);fence(14,12,10,6);
const cropArt=plantMaize({scene,box,cyl,ball,mats});sign('CROP BEDS',-8.4,2.5,20);
function tree(x,z,k=1){return orchardTree(scene,x,z,k)}for(let i=0;i<16;i++){tree(-26+i*3.5,-22,1+(i%3)*.15);if(i<12)tree(i%2?26:-26,-18+i*3.5,.8+(i%3)*.15)}for(let i=0;i<45;i++){let x=Math.sin(i*51)*26,z=Math.cos(i*27)*22;if(x>FIELD.minX&&x<FIELD.maxX&&z>FIELD.minZ&&z<FIELD.maxZ||Math.abs(x)<3||Math.abs(z-6)<3)continue;let o=mesh(new T.DodecahedronGeometry(.25+(i%3)*.13), '#a4ac8b',x,.3,z);o.scale.y=.6}
cyl(1.1,2.5,'#a1b7b2',-18,1.5,-11);cyl(1.3,.15,'#d1d7bf',-18,2.85,-11);for(let i=0;i<5;i++)box(1,.6,.65,'#e5c675',-14+i*.5,.5,-5);

return {worldBuildings,cropArt,tree,sign};
}
